// Configuration
const AFFILIATE_MARKUP_PERCENT = 5; // 5% markup
const PRICE_SELECTORS = ['.price', '.product-price', '.amount', '.currency'];

// Function to modify prices
function modifyPrice(element) {
  const originalText = element.textContent.trim();
  const originalPrice = parseFloat(originalText.replace(/[^0-9.]/g, ''));

  if (!isNaN(originalPrice)) {
    const newPrice = originalPrice * (1 + AFFILIATE_MARKUP_PERCENT / 100);
    const formattedPrice = newPrice.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    element.textContent = originalText.replace(originalPrice.toString(), formattedPrice);
  }
}

// Initial scan of the page
function scanPage() {
  PRICE_SELECTORS.forEach(selector => {
    document.querySelectorAll(selector).forEach(modifyPrice);
  });
}

// Watch for dynamically added content
const observer = new MutationObserver(() => {
  scanPage();
});
observer.observe(document.body, { childList: true, subtree: true });

// Run initial scan
scanPage();
